Boolean caught = false;
try {
    Account decoded = JSON.deserializeStrict('{"Name":"Acme","NoSuchField__c":"x"}', Account.class);
} catch (JSONException e) {
    caught = true;
    System.assert(e.getMessage().contains('unknown field "NoSuchField__c"'));
    System.assert(e.getMessage().contains('Account'));
}
System.assert(caught);
Account decodedOk = JSON.deserialize('{"Name":"Acme","NoSuchField__c":"x"}', Account.class);
System.assertEquals('Acme', decodedOk.Name);

